-- 6. Завдання перевірок рівня A2 (за id)
insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
select 'assessment_item', x.id, coalesce((select max(version) from public.content_versions where entity_type = 'assessment_item' and entity_id = x.id), 0) + 1,
       to_jsonb(x), 'curriculum_a2_v2: мовна перевірка 2026-11-12 — стара версія' from public.assessment_items x where x.id = '8c81d449-c1ca-599a-9abb-bd18edf38122' and ((x.prompt_ua, x.prompt_hr, x.options, x.correct_index, x.answer_text, x.audio_hr, x.passage_hr, x.passage_ua, x.explanation_ua, x.lesson_id) is distinct from ('Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li auto ikad bio udaren?', '["Я перший власник, і в мене всі рахунки із сервісу.", "Так. Рік випуску дві тисячі шістнадцятий, сто двадцять тисяч кілометрів.", "Ні. Приїжджайте й проїдьтеся."]'::jsonb, 2, null, null, 'Darja: Dobar dan, zovem zbog oglasa za auto. Je li još na prodaju?
Prodavač: Jest. Godište je dvije tisuće šesnaesto, sto dvadeset tisuća kilometara.
Darja: Jeste li prvi vlasnik? Imate li servisnu knjižicu?
Prodavač: Prvi sam vlasnik i imam sve račune iz servisa.
Darja: Je li auto ikad bio udaren?
Prodavač: Nije. Dođite pa se provozajte.', 'Darja: Добрий день, дзвоню щодо оголошення про авто. Воно ще продається?
Prodavač: Так. Рік випуску дві тисячі шістнадцятий, сто двадцять тисяч кілометрів.
Darja: Ви перший власник? У вас є сервісна книжка?
Prodavač: Я перший власник, і в мене всі рахунки із сервісу.
Darja: Авто колись було бите?
Prodavač: Ні. Приїжджайте й проїдьтеся.', 'Діалог «Дзвінок за оголошенням»: «Je li auto ikad bio udaren?» — «Nije. Dođite pa se provozajte.», тобто «Ні. Приїжджайте й проїдьтеся.».', (select id from public.lessons where id = '6a010148-5c1c-5e64-ab4a-c030b3adb969')));
